def get_geolocation_info(hostname):
    """
    Resolves the IP address of the given host and fetches geolocation information from ipinfo.io.

    Parameters:
    hostname (str): The hostname to resolve.

    Returns:
    dict: A dictionary containing geolocation information if successful, or an error message if not.
