        response = requests.get(f"https://ipinfo.io/{ip_address}/json", timeout=10)
        response.raise_for_status()  # Raise an HTTPError for bad responses (4xx and 5xx)
    except HTTPError as e:
        return {"error": f"HTTP error occurred while fetching geolocation data: {e}"}
    except ConnectionError as e:
        return {"error": f"Connection error occurred: {e}"}
    except Timeout as e:
        return {"error": f"Request timed out: {e}"}
    except RequestException as e:
        return {"error": f"An error occurred: {e}"}

    try:
        # Parse the JSON response
        geolocation_data = response.json()
    except ValueError as e:
        return {"error": f"Error parsing JSON response: {e}"}

