import socket
import ipaddress
import requests

def resolve_and_geolocate(host, timeout=5):
    """
    Resolve the given host to an IP address and fetch geolocation information from ipinfo.io.

    Parameters:
      host (str): Hostname or IP address (e.g., "example.com" or "8.8.8.8").
      timeout (float): Request timeout in seconds for the geolocation HTTP request (default: 5).

    Returns:
      dict: On success:
              {
                "success": True,
                "host": "<original host>",
                "ip": "<resolved ip>",
                "geo": { ... }   # parsed JSON from ipinfo.io
              }
            On failure:
              {
                "success": False,
                "host": "<original host>",
                "error": "<short error message>",
                "details": { ... }  # optional diagnostic information
              }

    Notes:
      - Uses requests and will call response.raise_for_status() (so HTTP errors are handled and reported).
      - Robust against invalid hostnames, network errors, HTTP errors, and JSON parsing errors.
      - Requires the requests package to be installed.
    """
    if not host or not isinstance(host, str):
        return {"success": False, "host": host, "error": "invalid_host", "details": {"message": "Host must be a non-empty string"}}

    # Step 1: Determine if the host is already an IP address
    ip = None
    try:
        # ipaddress will raise a ValueError if not a valid IP
        _ = ipaddress.ip_address(host)
        ip = host
    except ValueError:
        # Not a raw IP address; attempt DNS resolution
        try:
            # getaddrinfo returns a list; take the first resolved address
            # Prefer IPv4/IPv6 as returned by the system (first entry)
            infos = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
            if not infos:
                return {"success": False, "host": host, "error": "resolution_failed", "details": {"message": "No address info returned"}}
            # infos entries are tuples; address is at index [4][0]
            for info in infos:
                addr = info[4][0]
                if addr:
                    ip = addr
                    break
            if not ip:
                return {"success": False, "host": host, "error": "resolution_failed", "details": {"message": "Could not extract IP from getaddrinfo results"}}
        except socket.gaierror as e:
            return {"success": False, "host": host, "error": "dns_error", "details": {"message": str(e)}}
        except Exception as e:
            return {"success": False, "host": host, "error": "resolution_exception", "details": {"message": str(e)}}

    # Step 2: Query ipinfo.io for geolocation
    url = f"https://ipinfo.io/{ip}/json"
    headers = {"User-Agent": "resolve_and_geolocate/1.0"}
    try:
        resp = requests.get(url, timeout=timeout, headers=headers)
        # raise_for_status will raise requests.HTTPError on 4xx/5xx
        resp.raise_for_status()
    except requests.HTTPError as http_err:
        # Try to extract status code and text if available
        status = None
        text = None
        if hasattr(http_err, "response") and http_err.response is not None:
            status = http_err.response.status_code
            try:
                text = http_err.response.text
            except Exception:
                text = None
        return {
            "success": False,
            "host": host,
            "error": "http_error",
            "details": {
                "message": str(http_err),
                "status_code": status,
                "response_text": text,
                "url": url,
            },
        }
    except requests.RequestException as req_err:
        # Covers connection errors, timeouts, etc.
        return {
            "success": False,
            "host": host,
            "error": "request_exception",
            "details": {"message": str(req_err), "url": url},
        }

    # Step 3: Parse JSON response
    try:
        geo = resp.json()
    except ValueError as json_err:
        # JSON decoding error
        return {
            "success": False,
            "host": host,
            "error": "json_decode_error",
            "details": {"message": str(json_err), "response_text": resp.text[:1000]},
        }

    # Success
    return {"success": True, "host": host, "ip": ip, "geo": geo}


