from pathlib import Path
import csv
from typing import Optional

from openpyxl import load_workbook

def excel_to_csv(excel_path: str, csv_path: Optional[str] = None, sheet_name: Optional[str] = None) -> str:
    """
    Convert an Excel file to CSV.
    - excel_path: path to source Excel file (.xlsx, .xlsm, etc. supported by openpyxl). If it's .xls,
                  the function will attempt to use xlrd (if installed).
    - csv_path: optional destination path for CSV. If not provided, same name as excel_path with .csv.
    - sheet_name: optional sheet name to export. If not provided, the first (active) sheet is used.

    Returns the path to the created CSV file.

    Raises:
    - FileNotFoundError if excel_path doesn't exist
    - ValueError for unsupported/invalid sheet names or when .xls is supplied but xlrd is not available.
    - Other exceptions from openpyxl/xlrd are propagated.
    """
    excel_path = Path(excel_path)
    if not excel_path.exists():
        raise FileNotFoundError(f"Excel file not found: {excel_path}")

    if csv_path is None:
        csv_path = excel_path.with_suffix('.csv')
    else:
        csv_path = Path(csv_path)

    ext = excel_path.suffix.lower()

    # Helper to normalize cell values: convert None to empty string; otherwise string conversion.
    def _normalize(value):
        if value is None:
            return ''
        # openpyxl may give datetime/date/time objects; csv.writer will convert via str()
        return value

    # Use openpyxl for modern Excel files (.xlsx, .xlsm, .xltx, .xltm, ...)
    if ext in {'.xlsx', '.xlsm', '.xltx', '.xltm', '.ods'} or ext == '.xls' and False:
        # ext=='.xls' not handled here; handled below via xlrd fallback
        wb = load_workbook(filename=str(excel_path), read_only=True, data_only=True)
        if sheet_name:
            if sheet_name not in wb.sheetnames:
                raise ValueError(f"Sheet '{sheet_name}' not found in workbook. Available: {wb.sheetnames}")
            ws = wb[sheet_name]
        else:
            ws = wb[wb.sheetnames[0]]

        with open(csv_path, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            for row in ws.iter_rows(values_only=True):
                # write values directly; convert None to ''
                writer.writerow([_normalize(v) for v in row])

        wb.close()
        return str(csv_path)

    # If file is .xls, try to use xlrd (older format)
    if ext == '.xls':
        try:
            import xlrd
            from xlrd import xldate_as_datetime, XL_CELL_DATE
        except Exception as e:
            # xlrd not available or import error
            raise ValueError(
                "This looks like an old .xls file. openpyxl doesn't support .xls. "
                "Install xlrd (pip install xlrd) to enable .xls reading, or save the file as .xlsx."
            ) from e

        book = xlrd.open_workbook(str(excel_path), on_demand=True)
        if sheet_name:
            try:
                sheet = book.sheet_by_name(sheet_name)
            except xlrd.XLRDError:
                raise ValueError(f"Sheet '{sheet_name}' not found in workbook. Available: {book.sheet_names()}")
        else:
            sheet = book.sheet_by_index(0)

        with open(csv_path, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            for r in range(sheet.nrows):
                row_vals = []
                for c in range(sheet.ncols):
                    cell = sheet.cell(r, c)
                    val = cell.value
                    # convert Excel dates
                    if cell.ctype == XL_CELL_DATE:
                        try:
                            dt = xldate_as_datetime(val, book.datemode)
                            val = dt.isoformat()
                        except Exception:
                            val = str(val)
                    elif val is None:
                        val = ''
                    row_vals.append(val)
                writer.writerow(row_vals)
        book.release_resources()
        return str(csv_path)

    # Other extensions: try openpyxl anyway
    try:
        wb = load_workbook(filename=str(excel_path), read_only=True, data_only=True)
    except Exception as e:
        raise ValueError(f"Cannot read file '{excel_path}' with openpyxl: {e}") from e

    if sheet_name:
        if sheet_name not in wb.sheetnames:
            raise ValueError(f"Sheet '{sheet_name}' not found in workbook. Available: {wb.sheetnames}")
        ws = wb[sheet_name]
    else:
        ws = wb[wb.sheetnames[0]]

    with open(csv_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        for row in ws.iter_rows(values_only=True):
            writer.writerow([_normalize(v) for v in row])

    wb.close()
    return str(csv_path)
