def json_to_excel(json_str, filename):
    """
    Convert a JSON string to an Excel (.xls) file using xlwt.Workbook.
    - json_str: a JSON string representing either:
        * a list of objects (list of dicts),
        * a list of primitives,
        * a single object (dict),
        * or a single primitive.
    - filename: path to write the .xls file.

    Special handling:
    - If the JSON string is an empty array (i.e. "[]"), an Excel file will be created
      with a blank sheet (no data rows).
    """
    import json
    import xlwt

    def _format_value(v):
        # Convert nested structures to JSON strings, None to empty string, booleans to string.
        if v is None:
            return ""
        if isinstance(v, (dict, list)):
            # Preserve unicode characters
            return json.dumps(v, ensure_ascii=False)
        if isinstance(v, bool):
            return str(v)
        return v  # numbers and strings are fine

    try:
        data = json.loads(json_str)
    except Exception as e:
        raise ValueError("Invalid JSON: " + str(e))

    wb = xlwt.Workbook()
    ws = wb.add_sheet("Sheet1")

    # Handle an empty list -> produce an Excel with no data rows
    if isinstance(data, list):
        if len(data) == 0:
            # Leave sheet blank and save
            wb.save(filename)
            return
        # If list of dicts, produce header row from union of keys (preserving first-seen order)
        if all(isinstance(item, dict) for item in data):
            keys = []
            for item in data:
                for k in item.keys():
                    if k not in keys:
                        keys.append(k)
            # write headers
            for col, key in enumerate(keys):
                ws.write(0, col, key)
            # write rows
            for row_idx, item in enumerate(data, start=1):
                for col_idx, key in enumerate(keys):
                    ws.write(row_idx, col_idx, _format_value(item.get(key)))
        else:
            # list of primitives or mixed types -> single-column "value"
            ws.write(0, 0, "value")
            for row_idx, item in enumerate(data, start=1):
                ws.write(row_idx, 0, _format_value(item))

    elif isinstance(data, dict):
        # Single object: headers are keys, one data row
        keys = list(data.keys())
        for col, key in enumerate(keys):
            ws.write(0, col, key)
            ws.write(1, col, _format_value(data.get(key)))
    else:
        # Single primitive value -> two-row: header "value" and the value
        ws.write(0, 0, "value")
        ws.write(1, 0, _format_value(data))

    wb.save(filename)

# Example usage:
# json_to_excel('[{"a":1,"b":2},{"a":3,"c":4}]', "output.xls")
# json_to_excel('[]', "empty.xls")

def export_function_specs_to_csv(f_list, file_path):
    """
    Exports specifications of functions in f_list to a CSV file at file_path.

    CSV columns:
    - 'Function Name': The name of the function.
    - 'Number of Arguments': The number of arguments the function takes (if determinable).
    - 'Defaults': Default values for the function's arguments, if any (stringified dict).
    - 'Annotations': Type annotations of the function's arguments and return value, if any (stringified dict).
    - 'Is Lambda': Boolean indicating whether the function is a lambda.

    Parameters:
    - f_list: iterable of callables (functions).
    - file_path: path (str) to write the CSV file.

    The function writes the CSV and returns None.
    """
    import inspect
    import pandas as pd

    rows = []
    for f in f_list:
        # Basic function name and lambda check
        try:
            func_name = f.__name__
        except Exception:
            # Some callables might not have __name__
            func_name = type(f).__name__

        is_lambda = (func_name == "<lambda>")

        # Attempt to get signature; fall back if not possible (e.g., builtins)
        try:
            sig = inspect.signature(f)
        except (ValueError, TypeError):
            sig = None

        if sig is not None:
            params = sig.parameters
            num_args = len(params)

            # Defaults: collect parameters that have a default
            defaults_dict = {}
            for name, param in params.items():
                if param.default is not inspect._empty:
                    try:
                        defaults_dict[name] = repr(param.default)
                    except Exception:
                        defaults_dict[name] = "<unrepresentable>"

            # Annotations: collect parameter annotations and return annotation if present
            annotations_dict = {}
            for name, param in params.items():
                if param.annotation is not inspect._empty:
                    try:
                        annotations_dict[name] = repr(param.annotation)
                    except Exception:
                        annotations_dict[name] = "<unrepresentable>"

            if sig.return_annotation is not inspect._empty:
                try:
                    annotations_dict['return'] = repr(sig.return_annotation)
                except Exception:
                    annotations_dict['return'] = "<unrepresentable>"

            defaults_str = str(defaults_dict) if defaults_dict else ""
            annotations_str = str(annotations_dict) if annotations_dict else ""
        else:
            # Unknown/undeterminable signature (e.g., some builtins)
            num_args = None
            defaults_str = ""
            annotations_str = ""

        rows.append({
            'Function Name': func_name,
            'Number of Arguments': num_args,
            'Defaults': defaults_str,
            'Annotations': annotations_str,
            'Is Lambda': bool(is_lambda)
        })

    df = pd.DataFrame(rows, columns=[
        'Function Name',
        'Number of Arguments',
        'Defaults',
        'Annotations',
        'Is Lambda'
    ])
    df.to_csv(file_path, index=False)

