def get_github_user_ascii(username):
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary with the normalized data.

    Raises:
        requests.exceptions.HTTPError: if an HTTP error occurs (e.g., 404, 403, rate limit).
    """
    import requests
    from requests.exceptions import HTTPError
    import unicodedata

    def _normalize_str(s):
        # Decompose Unicode characters and drop non-ASCII parts
        return unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode('ascii')

    def _normalize_value(v):
        if isinstance(v, str):
            return _normalize_str(v)
        if isinstance(v, dict):
            # Normalize keys (if strings) and values recursively
            new = {}
            for k, val in v.items():
                new_key = _normalize_str(k) if isinstance(k, str) else k
                new[new_key] = _normalize_value(val)
            return new
        if isinstance(v, list):
            return [_normalize_value(item) for item in v]
        # leave numbers, booleans, None, etc. unchanged
        return v

    url = f'https://api.github.com/users/{username}'
    try:
        resp = requests.get(url, headers={'Accept': 'application/vnd.github.v3+json'}, timeout=10)
        resp.raise_for_status()  # raises requests.exceptions.HTTPError for non-2xx responses
    except HTTPError:
        # Re-raise HTTPError so callers can catch it as requested
        raise
    except requests.RequestException as exc:
        # Wrap network-level errors as HTTPError for uniform handling
        raise HTTPError(f'Error fetching {url}: {exc}')

    try:
        data = resp.json()
    except ValueError as exc:
        raise HTTPError(f'Invalid JSON response from {url}: {exc}')

    return _normalize_value(data)
