def get_github_user_ascii(username: str, timeout: float = 10.0) -> dict:
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    Raises:
        requests.exceptions.HTTPError: if the GitHub API returns an HTTP error status.
        requests.exceptions.RequestException: for other requests-related errors (timeouts, connection errors, etc.).
        ValueError / json.JSONDecodeError: if the response body is not valid JSON.
    """
    import unicodedata
    import requests
    from requests.exceptions import HTTPError

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json", "User-Agent": "github-user-ascii-client/1.0"}

    resp = requests.get(url, headers=headers, timeout=timeout)
    try:
        resp.raise_for_status()
    except HTTPError as e:
        # Re-raise with a bit more context while preserving the original exception
        raise HTTPError(f"GitHub API HTTP error for user '{username}': {e}") from e

    data = resp.json()

    def _normalize(obj):
        if isinstance(obj, str):
            # Decompose unicode characters and drop non-ASCII parts
            return unicodedata.normalize("NFKD", obj).encode("ascii", "ignore").decode("ascii")
        elif isinstance(obj, list):
            return [_normalize(item) for item in obj]
        elif isinstance(obj, dict):
            # Normalize both keys and values if keys are strings
            new = {}
            for k, v in obj.items():
                nk = _normalize(k) if isinstance(k, str) else k
                new[nk] = _normalize(v)
            return new
        else:
            return obj

    return _normalize(data)

