    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    - Fetches https://api.github.com/users/{username}.
    - Calls response.raise_for_status() to raise requests.exceptions.HTTPError on non-2xx.
    - Normalizes all strings (including dictionary keys) using NFKD and ASCII encoding,
      dropping non-ASCII characters.
    - Returns a dictionary (matching the JSON structure) with normalized string values.

    Raises:
      requests.exceptions.HTTPError: if the GitHub API responds with an HTTP error status.
      requests.exceptions.RequestException: for network-related errors (timeouts, DNS, etc).
      ValueError: if the response JSON cannot be decoded.
    """
    def _normalize_string(s):
        # Decompose Unicode characters (NFKD) then drop non-ASCII.
        return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")

    def _normalize(obj):
        # Recursively normalize strings in dicts and lists.
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                new_k = _normalize_string(k) if isinstance(k, str) else k
                new[new_k] = _normalize(v)
            return new
        elif isinstance(obj, list):
            return [_normalize(item) for item in obj]
        elif isinstance(obj, tuple):
            # Convert tuples to lists for normalized output (JSON originally uses lists).
            return [_normalize(item) for item in obj]
        elif isinstance(obj, str):
            return _normalize_string(obj)
        else:
            return obj

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json", "User-Agent": "github-user-normalizer/1.0"}

