        # Convert other request exceptions into a RequestException (preserve original).
        raise

    data = resp.json()  # may raise ValueError if invalid JSON
    return _normalize(data)

def mean_and_variance(L):
    """
    Compute the mean and (population) variance of all numeric elements in a nested list/tuple/array L.
    Uses numpy.var for the variance (ddof=0).
    Returns a tuple (mean, variance).
    Raises ValueError if no numeric elements are found and TypeError for unsupported element types.
    """
    import numpy as np
    import numbers

    def _flatten(x):
        if isinstance(x, numbers.Number):
            yield x
        elif isinstance(x, (list, tuple, np.ndarray)):
            for item in x:
                yield from _flatten(item)
        else:
            # try to iterate other iterables (but not strings/bytes)
            if isinstance(x, (str, bytes)):
                raise TypeError(f"Unsupported element type: {type(x)}")
            try:
                for item in x:
                    yield from _flatten(item)
            except TypeError:
                raise TypeError(f"Unsupported element type: {type(x)}")

    vals = list(_flatten(L))
    if len(vals) == 0:
        raise ValueError("No numeric elements found in input")

    arr = np.array(vals, dtype=float)
    mean = arr.mean()
    variance = np.var(arr)  # population variance (ddof=0)
    return mean, variance

# Example:
# mean_and_variance([[1, 2], [3, [4, 5]]])  -> (3.0, 2.0)

def mean_and_var(L):
    """
    Compute the mean and variance of all numeric elements in a nested list `L`.
    Uses numpy.var for the variance calculation.
    Returns a tuple (mean, variance) as Python floats.

    Raises:
      ValueError: if no numeric elements are found or a non-numeric element is encountered.
    """
    import numpy as np

    def _flatten(x):
        # Recursively yield non-list/tuple/ndarray items
        if isinstance(x, (list, tuple, np.ndarray)):
            for item in x:
                yield from _flatten(item)
        else:
            yield x

    values = []
    for item in _flatten(L):
        try:
            values.append(float(item))
        except (TypeError, ValueError):
            raise ValueError(f"Non-numeric element encountered: {item!r}")

    if not values:
        raise ValueError("Input contains no numeric elements")

    arr = np.array(values, dtype=float)
    mean = float(arr.mean())
    var = float(np.var(arr))  # using numpy.var as requested
    return mean, var

