def nested_list_mode(L):
    """
    Compute the mode of all elements in a nested list `L` using scipy.stats.mode.
    Returns the single mode value. Raises ValueError if there are no elements.

    Example:
        nested_list_mode([[1, 2, 2], [3, 2]])  # -> 2
    """
    from scipy.stats import mode
    import numpy as np

    def _flatten(x):
        for el in x:
            # treat lists/tuples as containers; keep strings/bytes as scalars
            if isinstance(el, (list, tuple)):
                yield from _flatten(el)
            else:
                yield el

    flat = list(_flatten(L))
    if not flat:
        raise ValueError("Input nested list contains no elements")

    arr = np.array(flat, dtype=object)
    res = mode(arr, axis=None)
    return res.mode.item()

