def median_nested(L):
    """
    Calculate the median of all numeric elements in a nested list/iterable L,
    using numpy.sort.

    Returns a float. Raises ValueError if L contains no elements and TypeError
    if elements cannot be cast to numbers.
    """
    def _flatten(x):
        # treat common container types as nested; atomic values are yielded
        if isinstance(x, (list, tuple, set, np.ndarray)):
            for item in x:
                yield from _flatten(item)
        else:
            yield x

    # If someone passed a non-iterable scalar, treat it as single element
    if not isinstance(L, (list, tuple, set, np.ndarray)):
        flat = [L]
    else:
        flat = list(_flatten(L))

    if len(flat) == 0:
        raise ValueError("No elements to compute median from.")

    try:
        arr = np.array(flat, dtype=float)
    except Exception as e:
        raise TypeError("Elements must be numeric and convertible to float.") from e

    sorted_arr = np.sort(arr)  # use numpy.sort as requested
    n = sorted_arr.size
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_arr[mid])
    else:
        return float((sorted_arr[mid - 1] + sorted_arr[mid]) / 2.0)

