def iqr_nested(L, nan_policy='omit'):
    """
    Compute the interquartile range (IQR) of all numeric elements in a nested list/iterable L
    using scipy.stats.iqr.

    Parameters:
      L : nested iterable (lists, tuples, sets, numpy arrays, etc.) containing numeric values
      nan_policy : str, passed to scipy.stats.iqr (e.g. 'omit' or 'propagate')

    Returns:
      float: the IQR of all numeric elements

    Raises:
      ValueError: if no numeric elements are found
      TypeError: if a non-numeric element is encountered that cannot be converted to float
    """
    from collections.abc import Iterable
    import numpy as np
    from scipy.stats import iqr

    def _flatten(x):
        # Do not treat strings/bytes as iterables to avoid iterating characters
        if isinstance(x, (str, bytes, bytearray)):
            yield x
        elif isinstance(x, Iterable):
            for item in x:
                yield from _flatten(item)
        else:
            yield x

    nums = []
    for item in _flatten(L):
        try:
            # convert to float to ensure numeric; will raise for non-numeric items
            nums.append(float(item))
        except Exception:
            raise TypeError(f"Non-numeric element encountered in nested input: {item!r}")

    if not nums:
        raise ValueError("No numeric elements found in nested input.")

    arr = np.array(nums, dtype=float)
    return float(iqr(arr, axis=None, nan_policy=nan_policy))

import numpy as np

def move_first3_to_end(l):
    """
    Convert list l to a NumPy array and move the first 3 elements to the end.
    If the list has fewer than 3 elements, rotation is done modulo the length.
    """
    arr = np.array(l)
    n = arr.size
    if n == 0:
        return arr
    k = 3 % n
    if k == 0:
        return arr.copy()
    return np.concatenate((arr[k:], arr[:k]))

def most_common_per_column(csv_path):
    """
    Read a CSV file with column names and return a dict mapping each column name
    to its most common value (ties broken alphabetically).
    Uses numpy.genfromtxt to read the file.

    If the CSV is empty or contains no data rows, returns an empty dict.

    Parameters:
      csv_path: path to the CSV file (string)

    Returns:
      dict: {column_name: most_common_value_as_string, ...}
    """
    import numpy as np
    from collections import Counter
    import os

    # If file is empty, return empty dict
    try:
        if os.path.getsize(csv_path) == 0:
            return {}
    except (OSError, TypeError):
        # If path is invalid or not a filesystem path, let genfromtxt try and handle errors
        pass

    try:
        data = np.genfromtxt(csv_path, delimiter=',', dtype=None, names=True, encoding='utf-8', autostrip=True)
    except Exception:
        # Any read error (including no header) => treat as empty
        return {}

    # If genfromtxt returned an empty array (no data rows), return empty dict
    try:
        if np.size(data) == 0:
            return {}
    except Exception:
        return {}

    # If no named fields, nothing to do
    if getattr(data, 'dtype', None) is None or data.dtype.names is None:
        return {}

    result = {}
    for name in data.dtype.names:
        col = data[name]
        # Handle masked arrays (missing values)
        if isinstance(col, np.ma.MaskedArray):
            valid = col[~col.mask]
            values = valid.tolist()
        else:
            # Ensure column is iterable even if single row -> convert to 1D list
            values = np.atleast_1d(col).tolist()

        # Convert all values to strings for consistent alphabetical tie-breaking
        str_values = ['' if v is None else str(v) for v in values]

        # If there are no values (shouldn't happen after checks), skip
        if not str_values:
            continue

        counts = Counter(str_values)
        max_count = max(counts.values())
        # Select all values that tie for max, sort alphabetically, pick first
        candidates = [v for v, c in counts.items() if c == max_count]
        chosen = sorted(candidates)[0]
        result[name] = chosen

    return result

