    result = {}
    names = arr.dtype.names or ()
    for name in names:
        col = arr[name]
        # If single-row data, col can be a scalar; make a list in that case
        if np.isscalar(col):
            values = [str(col).strip()]
        else:
            # Convert all entries to strings and strip surrounding whitespace
            values = [str(v).strip() for v in col]

        # Count occurrences
        counts = {}
        for v in values:
            counts[v] = counts.get(v, 0) + 1

        # Find value(s) with maximum count
        max_count = max(counts.values())
        candidates = [v for v, c in counts.items() if c == max_count]
        candidates.sort()  # alphabetical tie-breaker
        result[name] = candidates[0]

