```python
from typing import Any, List, Optional, Union, Tuple
from numbers import Number
import seaborn as sns
import matplotlib.pyplot as plt

def json_boxplot(
    json_obj: Any,
    path: Union[str, List[Union[str, int]]],
    ax: Optional[plt.Axes] = None,
    figsize: Tuple[int, int] = (8, 6),
    orient: str = "v",
    title: Optional[str] = None,
    showfliers: bool = True,
    color: Optional[Union[str, dict]] = None,
    seaborn_kwargs: Optional[dict] = None,
    return_data: bool = False,
):
    """
    Extract numerical values from a nested JSON-like object following `path`
    and plot a seaborn.boxplot of those values.

    Parameters:
    - json_obj: nested python structure (dicts/lists) typically from json.load(...)
    - path: either a dot-separated string (e.g. "records.*.value")
            or a list of keys (e.g. ["records", "*", "value"]).
            Use "*" to iterate over all elements at that level.
            Path elements may be strings or integers (for list indices).
    - ax: optional matplotlib axes to draw into. If None, a new figure/axes is created.
    - figsize: size of figure when ax is None.
    - orient: "v" for vertical boxplot (default), "h" for horizontal.
    - title: optional plot title.
    - showfliers: whether to show outliers (forwarded to seaborn.boxplot).
    - color: color argument forwarded to seaborn.boxplot.
    - seaborn_kwargs: optional dict of additional kwargs forwarded to seaborn.boxplot.
    - return_data: if True, the function returns a tuple (ax, values). Otherwise returns ax.

    Returns:
    - ax (or (ax, values) if return_data is True)

    Behavior notes:
    - Numeric values include ints/floats and other Number types, but booleans are excluded.
    - If no numeric values found, ValueError is raised.
    - If the final matched object is a nested list/dict it will be searched for numeric leaves.
    """

    if isinstance(path, str):
        # split on dots; strip whitespace
        path_elems = [p.strip() for p in path.split(".") if p.strip() != ""]
    else:
        path_elems = list(path)

    if seaborn_kwargs is None:
        seaborn_kwargs = {}

    # helper to collect numeric leaves from an arbitrary nested structure
    def collect_numbers(obj: Any, out: List[float]):
        if obj is None:
            return
        if isinstance(obj, dict):
            for v in obj.values():
                collect_numbers(v, out)
        elif isinstance(obj, (list, tuple, set)):
            for item in obj:
                collect_numbers(item, out)
        else:
            # accept numeric types but exclude booleans
            if isinstance(obj, Number) and not isinstance(obj, bool):
                out.append(float(obj))

    # recursive traversal following the path
    values: List[float] = []
    def recurse(node: Any, idx: int):
        if node is None:
            return
        if idx >= len(path_elems):
            # reached end of path: collect numeric leaves below this node
            collect_numbers(node, values)
            return

        key = path_elems[idx]

        # wildcard - iterate over all values in dict or items in list
        if key == "*":
            if isinstance(node, dict):
                for v in node.values():
                    recurse(v, idx + 1)
            elif isinstance(node, (list, tuple)):
                for item in node:
                    recurse(item, idx + 1)
            else:
                # nothing to iterate
                return
            return

        # try to interpret key as integer index if possible
        key_is_index = False
        try:
            key_index = int(key) if not isinstance(key, int) else key
            key_is_index = True
        except Exception:
            key_is_index = False

        if key_is_index:
            if isinstance(node, (list, tuple)):
                if 0 <= key_index < len(node):
                    recurse(node[key_index], idx + 1)
            # if node is dict but has integer-string key we can try that fallback:
            elif isinstance(node, dict):
                # fallback: if node contains that integer key as string or int
                if key_index in node:
                    recurse(node[key_index], idx + 1)
                elif str(key_index) in node:
                    recurse(node[str(key_index)], idx + 1)
            return

        # key is a string name
        if isinstance(node, dict):
            if key in node:
                recurse(node[key], idx + 1)
            elif str(key) in node:
                recurse(node[str(key)], idx + 1)
        elif isinstance(node, (list, tuple)):
            # iterate items; if items are dicts and contain the key, recurse on them
            for item in node:
                if isinstance(item, dict) and key in item:
                    recurse(item[key], idx + 1)
        else:
            # nothing to do on scalars
            return

    recurse(json_obj, 0)

    if not values:
        raise ValueError(f"No numeric values found for path: {path}")

    # plotting
    if ax is None:
        fig, ax = plt.subplots(figsize=figsize)
    if orient not in ("v", "h"):
        raise ValueError("orient must be 'v' or 'h'")

    plot_kwargs = dict(seaborn_kwargs)  # copy
    plot_kwargs.update(dict(showfliers=showfliers))
    if color is not None:
        plot_kwargs.update(dict(color=color))

    if orient == "v":
        sns.boxplot(y=values, ax=ax, **plot_kwargs)
        ax.set_ylabel("value")
    else:
        sns.boxplot(x=values, ax=ax, **plot_kwargs)
        ax.set_xlabel("value")

    if title:
        ax.set_title(title)

    ax.grid(True, linestyle=":", linewidth=0.5, alpha=0.7)

    if return_data:
        return ax, values
    return ax

# Example usage:
# data = {
#     "records": [
#         {"id": 1, "value": 10},
#         {"id": 2, "value": 12},
#         {"id": 3, "value": 9}
#     ]
# }
