Note: this function requires sklearn and matplotlib to be installed.

```python
import json
import numbers
import numpy as np
import matplotlib.pyplot as plt
from sklearn.preprocessing import MinMaxScaler

def process_json_minmax_plot(
    json_str,
    key=None,
    title=None,
    xlabel='index',
    ylabel='normalized value',
    figsize=(8, 4),
    save_path=None,
    show=True
):
    """
    Parse a JSON string, extract a numeric sequence, apply Min-Max normalization,
    and produce a line plot of the normalized sequence.

    Parameters:
    - json_str (str): JSON-formatted string containing numeric data.
    - key (str or None): If the JSON is an object or list of objects, the key to extract numeric values from.
                         If None, the function will attempt to auto-detect a numeric list in the JSON structure.
    - title (str or None): Plot title. If None, a default title is used.
    - xlabel (str): Label for the x-axis.
    - ylabel (str): Label for the y-axis.
    - figsize (tuple): Matplotlib figure size.
    - save_path (str or None): If provided, the plot will be saved to this path (e.g., 'plot.png').
    - show (bool): If True, plt.show() is called. Set to False when running in non-GUI environments.

    Returns:
    - normalized (np.ndarray): 1-D array of normalized values (range [0, 1]). Length equals number of extracted numeric entries.

    Raises:
    - ValueError: If no numeric data can be extracted from the provided JSON.
    """

    def is_number(x):
        return isinstance(x, numbers.Number) and not isinstance(x, bool)

    def try_float(x):
        # Accept numeric strings too
        if is_number(x):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except ValueError:
                return None
        return None

    # Parse JSON
    try:
        data = json.loads(json_str)
    except Exception as e:
        raise ValueError(f"Invalid JSON string: {e}")

    candidate = None

    # If top-level is list
    if isinstance(data, list):
        # list of plain numbers?
        if all(is_number(el) or isinstance(el, str) for el in data):
            candidate = data
        # list of dicts?
        elif all(isinstance(el, dict) for el in data):
            if key is not None:
                candidate = [el.get(key) for el in data]
            else:
                # try to find a key that yields numeric-like values across most entries
                keys = set().union(*(d.keys() for d in data))
                best_key = None
                best_count = -1
                for k in keys:
                    vals = [try_float(d.get(k)) for d in data]
                    count_valid = sum(1 for v in vals if v is not None)
                    if count_valid > best_count:
                        best_count = count_valid
                        best_key = k
                if best_key is not None and best_count > 0:
                    candidate = [d.get(best_key) for d in data]
    # If top-level is dict
    elif isinstance(data, dict):
        if key is not None and key in data:
            candidate = data[key]
        else:
            # find first value that's a list of numbers or list of dicts
            for k, v in data.items():
                if isinstance(v, list):
                    # list of numbers
                    if all(is_number(el) or isinstance(el, str) for el in v):
                        candidate = v
                        break
                    # list of dicts: try to extract best numeric key
                    if all(isinstance(el, dict) for el in v):
                        keys = set().union(*(d.keys() for d in v))
                        best_key = None
                        best_count = -1
                        for kk in keys:
                            vals = [try_float(d.get(kk)) for d in v]
                            count_valid = sum(1 for vv in vals if vv is not None)
                            if count_valid > best_count:
                                best_count = count_valid
                                best_key = kk
                        if best_key is not None and best_count > 0:
                            candidate = [d.get(best_key) for d in v]
                            break
            # fallback: maybe a single numeric value -> treat as single-element series
            if candidate is None:
                # look for any numeric scalar in dict
                for v in data.values():
                    if is_number(v) or (isinstance(v, str) and try_float(v) is not None):
                        candidate = [v]
                        break

    # If candidate not found yet, try to extract numeric values anywhere by traversing
    if candidate is None:
        extracted = []

        def extract_numbers(obj):
            if isinstance(obj, dict):
                for vv in obj.values():
                    extract_numbers(vv)
            elif isinstance(obj, list):
                for item in obj:
                    extract_numbers(item)
            else:
                f = try_float(obj)
                if f is not None:
                    extracted.append(f)

        extract_numbers(data)
        if extracted:
            candidate = extracted

    if candidate is None:
        raise ValueError("Could not find any numeric sequence in the provided JSON.")

    # Convert candidate to numeric list, keeping only convertible entries
    nums = []
    for el in candidate:
        fv = try_float(el)
        if fv is not None:
            nums.append(fv)

    if len(nums) == 0:
        raise ValueError("No numeric entries could be parsed from the extracted data.")

    arr = np.array(nums, dtype=float).reshape(-1, 1)

    # Apply MinMaxScaler
    scaler = MinMaxScaler()
    normalized = scaler.fit_transform(arr).ravel()  # 1-D array

    # Plot normalized sequence
    fig, ax = plt.subplots(figsize=figsize)
    ax.plot(normalized, marker='o', linestyle='-')
    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel)
    ax.set_title(title if title is not None else "Min-Max Normalized Series")
    ax.grid(True)

    if save_path:
        plt.savefig(save_path, bbox_inches='tight')

    if show:
        plt.show()
    else:
        plt.close(fig)

    return normalized
```

Example usage:
- JSON is a list of numbers: '[1, 4, 2, 10]'
- JSON is an object with a numeric list: '{"values": [1,4,2,10]}' and call with key="values"
- JSON is a list of objects: '[{"time":1,"val":10},{"time":2,"val":20}]' and call with key="val" (or omit key to auto-detect)

The function will raise a ValueError if no numeric sequence can be found.

