                            candidate = str(comment)
                            sc = printable_score(candidate)
                            if sc > best_score + 1e-6:
                                best_text, best_score = candidate, sc

            # Final fallback: try one more re-encode pass on whatever best_text we have
            if best_text:
                final_candidate = try_fix_encodings(best_text)
                if printable_score(final_candidate) > best_score:
                    best_text = final_candidate

            return best_text or ''
    except FileNotFoundError:
        raise
    except Exception as ex:
        # Unexpected errors: return empty string but raise for visibility is optional.
        # Re-raise to let caller handle if desired. For now, re-raise.
        raise RuntimeError(f"Failed to extract text from '{image_path}': {ex}") from ex

