from typing import Optional, Iterable
import string

from PIL import Image, ExifTags
import pytesseract


def ocr_read_and_convert(
    image_path: str,
    lang: Optional[str] = None,
    config: str = "",
    try_encodings: Optional[Iterable[str]] = None,
) -> str:
    """
    Open an image, extract text via pytesseract.image_to_string, attempt to fix encoding
    (common mojibake patterns) and, if OCR output is empty or looks garbled, fall back to
    image comment / EXIF user comment processing.

    Parameters:
    - image_path: path to the image file
    - lang: optional Tesseract language code(s), passed to pytesseract.image_to_string
    - config: optional Tesseract config string (e.g. '--psm 6')
    - try_encodings: iterable of encodings to try when attempting to repair mojibake.
      If None, a reasonable default list is used.

    Returns:
    - Unicode string with the best-guess text extracted/converted from the image.
    """
    if try_encodings is None:
        try_encodings = [
            "utf-8",
            "cp1252",
            "iso-8859-1",
            "utf-16",
            "utf-16le",
            "shift_jis",
            "euc-jp",
        ]

    def printable_ratio(s: str) -> float:
        if not s:
            return 0.0
        allowed = set(string.printable)
        valid = sum(1 for ch in s if ch in allowed or ch.isspace())
        return valid / max(1, len(s))

    def repair_mojibake(orig: str) -> str:
        """
        Attempt to repair mojibake by reinterpreting the original Python str bytes
        (via latin-1 encoding) as actual bytes and decoding with alternative encodings.
        Return the best candidate by printable ratio.
        """
        candidates = [orig]
        # If orig is already str, we can interpret its underlying bytes using latin-1
        # to recover the original byte sequence that may have been mis-decoded earlier.
        try:
            raw_bytes = orig.encode("latin-1", errors="ignore")
        except Exception:
            raw_bytes = None

        if raw_bytes:
            for enc in try_encodings:
                try:
                    decoded = raw_bytes.decode(enc, errors="ignore")
                    if decoded and decoded != orig:
                        candidates.append(decoded)
                except Exception:
                    continue

        # Also try simple re-encodes/decodes that sometimes help
        for enc in try_encodings:
            try:
                roundtrip = orig.encode(enc, errors="ignore").decode(
                    enc, errors="ignore"
                )
                if roundtrip and roundtrip != orig:
                    candidates.append(roundtrip)
            except Exception:
                pass

        # score and return best
        best = max(candidates, key=printable_ratio)
        return best

    def read_image_comments(img: Image.Image) -> str:
        """
        Extract textual comments from common image metadata locations:
        - PNG/JPEG Image.info['comment'] if present
        - EXIF tags such as UserComment, ImageDescription, XPComment, XPTitle
        Returns the best-scoring textual candidate or empty string.
        """
        candidates = []

        info = getattr(img, "info", {}) or {}
        comment = info.get("comment")
        if isinstance(comment, bytes):
            # try a few decodings
            for enc in ("utf-8", "utf-16le", "latin-1", "cp1252"):
                try:
                    txt = comment.decode(enc, errors="ignore")
                    if txt:
                        candidates.append(txt)
                except Exception:
                    pass
        elif isinstance(comment, str) and comment:
            candidates.append(comment)

        # EXIF
        try:
            exif = img._getexif()
        except Exception:
            exif = None

        if exif:
            # map tag ids to names
            tag_map = {v: k for k, v in ExifTags.TAGS.items()}
            # common textual tags
            textual_tags = {"UserComment", "ImageDescription", "XPComment", "XPTitle"}
            for tag_id, value in exif.items():
                tag_name = ExifTags.TAGS.get(tag_id, None)
                if tag_name in textual_tags and value:
                    # value may be bytes or str
                    if isinstance(value, bytes):
                        for enc in ("utf-8", "utf-16le", "latin-1", "cp1252"):
                            try:
                                txt = value.decode(enc, errors="ignore")
                                if txt:
                                    candidates.append(txt)
                            except Exception:
                                pass
                    elif isinstance(value, str):
                        candidates.append(value)

        # Score and return best
        if not candidates:
            return ""
        best = max(candidates, key=printable_ratio)
        return best

    # Main flow
    with Image.open(image_path) as img:
        # Run OCR
        try:
            ocr_kwargs = {}
            if lang:
                ocr_kwargs["lang"] = lang
            # pytesseract expects an Image object or path; we pass the opened Image
            raw_text = pytesseract.image_to_string(img, config=config, **ocr_kwargs)
            if raw_text is None:
                raw_text = ""
        except Exception as e:
            # If OCR fails, try to fall back to comments immediately
            raw_text = ""
            # We don't re-raise; will try comments below

        # Attempt repair
        repaired = repair_mojibake(raw_text)

        # Choose best between raw and repaired
        best_candidate = max([raw_text, repaired], key=printable_ratio)

        # If OCR output is empty or very low quality, try image comments / EXIF
        if printable_ratio(best_candidate) < 0.30:
            comment_text = read_image_comments(img)
            # also try repairing comment text (if any)
            if comment_text:
                comment_repaired = repair_mojibake(comment_text)
                # choose the best among current best, comment, and repaired comment
                best_candidate = max(
                    [best_candidate, comment_text, comment_repaired], key=printable_ratio
                )

    # Final cleanup: strip leading/trailing whitespace but preserve internal newlines
    return best_candidate.strip()
