Copy-paste and use as-is (requires Pillow and pytesseract installed and tesseract available on PATH).

def extract_text_from_image(path, lang=None, psm=None, oem=None):
    """
    Open an image file, perform OCR using pytesseract.image_to_string,
    normalize/convert encodings, and if OCR yields no useful text,
    fall back to extracting and decoding image comments/metadata.

    Args:
        path (str): Path to image file.
        lang (str, optional): Language code for pytesseract (e.g. 'eng'). Default None.
        psm (int, optional): Page segmentation mode for Tesseract (--psm). Default None.
        oem (int, optional): OCR Engine mode for Tesseract (--oem). Default None.

    Returns:
        str or None: Extracted text (possibly from OCR or image metadata), or None if nothing found.
    """
    try:
        from PIL import Image, ExifTags
    except Exception as e:
        raise ImportError("Pillow is required (pip install pillow). Error: {}".format(e))
    try:
        import pytesseract
    except Exception as e:
        raise ImportError("pytesseract is required (pip install pytesseract). Error: {}".format(e))

    def safe_decode_bytes(value):
        """Try several decodings for byte-like EXIF/comment fields."""
        if value is None:
            return None
        # If it's a sequence of ints (XP* fields often are), convert to bytes
        if isinstance(value, (list, tuple)):
            try:
                b = bytes(value)
            except Exception:
                # fallback: join ints mod 256
                try:
                    b = bytes([int(x) & 0xFF for x in value])
                except Exception:
                    return None
            # Many XP fields are UTF-16-LE with trailing nulls
            try:
                s = b.decode('utf-16le', errors='replace').rstrip('\x00')
                if s.strip():
                    return s
            except Exception:
                pass
            # try other decodes after forming bytes
            value = b

        # If it's already a str, return as-is
        if isinstance(value, str):
            return value

        # Now value is likely bytes
        if isinstance(value, bytes):
            b = value
            # EXIF UserComment may start with charset signature like b'ASCII\0\0\0' or b'UNICODE\0'
            if b.startswith(b'ASCII\0\0\0'):
                try:
                    return b[8:].decode('ascii', errors='replace').strip('\x00')
                except Exception:
                    pass
            if b.startswith(b'UNICODE\0') or b.startswith(b'UNICODE\0\0'):
                try:
                    return b[8:].decode('utf-16', errors='replace').strip('\x00')
                except Exception:
                    pass
            if b.startswith(b'JIS\0\0\0'):
                try:
                    return b[8:].decode('shift_jis', errors='replace').strip('\x00')
                except Exception:
                    pass

            # Try common encodings robustly
            for enc in ('utf-8', 'utf-16', 'utf-16le', 'utf-16be', 'cp1252', 'latin-1', 'shift_jis'):
                try:
                    s = b.decode(enc, errors='replace').strip('\x00')
                    if s.strip():
                        return s
                except Exception:
                    continue
        # nothing worked
        return None

    def extract_comments_from_image(img):
        """Extract candidate comment strings from PIL image metadata and EXIF."""
        candidates = []

        # PNG and some formats place comments in image.info
        info = getattr(img, 'info', {}) or {}
        # common keys: 'comment', 'Description', 'Comment', 'XML:com.adobe.xmp', etc.
        for key in ('comment', 'Comment', 'DESCRIPTION', 'Description', 'ImageDescription'):
            if key in info:
                decoded = safe_decode_bytes(info[key])
                if decoded:
                    candidates.append(decoded)

        # For PNG textual chunks, PIL may include 'text' dict under 'text' or 'txt'
        try:
            textdict = info.get('text') or info.get('texts') or info.get('PNG_TEXT') or {}
            if isinstance(textdict, dict):
                for k, v in textdict.items():
                    decoded = safe_decode_bytes(v)
                    if decoded:
                        candidates.append("{}: {}".format(k, decoded))
        except Exception:
            pass

        # Extract EXIF fields if present
        try:
            exif = img.getexif()
        except Exception:
            exif = None

        if exif:
            # Map numeric tags to names
            tag_map = {}
            for tag_id, value in exif.items():
                tag_name = ExifTags.TAGS.get(tag_id, tag_id)
                tag_map[tag_name] = value

            # Look for common textual tags
            for key in ('UserComment', 'ImageDescription', 'XPComment', 'XPTitle', 'XPSubject', 'XPAuthor', 'DocumentName'):
                if key in tag_map:
                    decoded = safe_decode_bytes(tag_map[key])
                    if decoded:
                        candidates.append(decoded)

        # Also check img.info.get('exif') raw bytes (JPEG APP1) - usually binary, but could contain ASCII
        raw_exif = info.get('exif')
        if raw_exif and isinstance(raw_exif, (bytes, bytearray)):
            # simple ascii search for printable sequences of length >= 4
            try:
                import re
                s = raw_exif.decode('latin-1', errors='ignore')
                # find printable runs
                runs = re.findall(r'[ -~]{4,}', s)
                for r in runs:
                    candidates.append(r)
            except Exception:
                pass

        # Filter and return unique non-empty candidates
        seen = set()
        out = []
        for c in candidates:
            c2 = c.strip()
            if c2 and c2 not in seen:
                seen.add(c2)
                out.append(c2)
        return out

    # Try opening the image
    try:
        img = Image.open(path)
    except Exception as e:
        raise IOError("Cannot open image {}: {}".format(path, e))

    # Build tesseract config
    config_parts = []
    if psm is not None:
        config_parts.append("--psm {}".format(int(psm)))
    if oem is not None:
        config_parts.append("--oem {}".format(int(oem)))
    config = " ".join(config_parts) if config_parts else None

    # Perform OCR
    try:
        if config and lang:
            raw_text = pytesseract.image_to_string(img, lang=lang, config=config)
        elif config:
            raw_text = pytesseract.image_to_string(img, config=config)
        elif lang:
            raw_text = pytesseract.image_to_string(img, lang=lang)
        else:
            raw_text = pytesseract.image_to_string(img)
    except Exception as e:
        # If OCR fails, move to comment fallback
        raw_text = None

    if raw_text:
        cleaned = raw_text.strip()
        if cleaned:
            return cleaned

    # OCR gave nothing useful -> try metadata/comment fallback
    comments = extract_comments_from_image(img)
    if comments:
        # Return first non-empty candidate
        return comments[0]

    # Nothing found
    return None

