import re
import requests
from urllib.parse import urlparse

def extract_domains_geolocations(text, ip_api_base="http://ip-api.com/json/", timeout=5):
    """
    Extract all URLs/domains from the provided text, normalize to domains, and query the IP-API
    (default: http://ip-api.com/json/{domain}) for geolocation data for each domain.

    Returns a dict mapping domain -> result where result is either:
      - {'success': True, 'data': <api json dict>} on success
      - {'success': False, 'error': <error message>} on failure

    Parameters:
      text (str): input text that may contain URLs or bare domains.
      ip_api_base (str): base URL for the IP API; domain will be appended (default ip-api.com).
      timeout (float): timeout in seconds for the requests.get calls.

    Requires: requests library.
    """
    # Patterns:
    # 1) URLs that start with http/https or www.
    url_pattern = re.compile(r'(?:(?:https?://)|www\.)[^\s<>()\[\]\'"{}]+', re.IGNORECASE)
    # 2) Bare domain names like example.com (captures domain part)
    domain_pattern = re.compile(
        r'\b((?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,})(?::\d+)?\b',
        re.IGNORECASE
    )

    # Collect candidates with their position to preserve order of first appearance
    candidates = []
    for m in url_pattern.finditer(text):
        candidates.append((m.start(), m.group()))
    for m in domain_pattern.finditer(text):
        candidates.append((m.start(), m.group(1)))  # group(1) is the domain part

    # Sort by position and deduplicate (case-insensitive)
    candidates.sort(key=lambda x: x[0])
    seen = set()
    domains = []
    for _, token in candidates:
        token = token.strip(".,;:()[]\"'")  # trim common trailing/leading punctuation
        # If token looks like a URL (starts with scheme or www), parse it to extract hostname
        parsed = None
        if re.match(r'^(?:https?://)', token, re.IGNORECASE) or token.lower().startswith("www."):
            # Ensure scheme for parsing
            if not re.match(r'^[a-zA-Z]+://', token):
                token_for_parse = "http://" + token
            else:
                token_for_parse = token
            parsed = urlparse(token_for_parse)
            hostname = parsed.hostname
        else:
            # token is likely a bare domain
            hostname = token

        if not hostname:
            continue
        hostname = hostname.lower().strip()
        if hostname not in seen:
            seen.add(hostname)
            domains.append(hostname)

    results = {}
    for domain in domains:
        url = ip_api_base.rstrip('/') + '/' + domain
        try:
            resp = requests.get(url, timeout=timeout)
        except requests.RequestException as e:
            results[domain] = {'success': False, 'error': f'request error: {e}'}
            continue

        if resp.status_code != 200:
            results[domain] = {'success': False, 'error': f'HTTP {resp.status_code}'}
            continue

        try:
            data = resp.json()
        except ValueError:
            results[domain] = {'success': False, 'error': 'invalid JSON response'}
            continue

        # ip-api returns {"status":"success", ...} or {"status":"fail","message":"..."}
        if isinstance(data, dict) and data.get('status') == 'success':
            results[domain] = {'success': True, 'data': data}
        else:
            # include message if present
            msg = data.get('message') if isinstance(data, dict) else None
            results[domain] = {'success': False, 'error': f'API failure: {msg}' if msg else 'API failure'}

    return results

# Example usage:
# text = "Check https://www.example.com/path and http://sub.domain.org, also visit example.net."
# print(extract_domains_geolocations(text))

def extract_urls_geolocate(text: str, timeout: int = 5):
    """
    Extract all URLs from the provided text, determine each URL's domain, and
    query the IP-API (http://ip-api.com) for geolocation data for each domain.
    Uses requests.get for HTTP calls.

    Returns a dict mapping each extracted URL (as found or normalized) to a
    result dict:
      {
        "<url>": {
          "domain": "<hostname>" or None,
          "geo": { ... }      # JSON returned by ip-api when successful
          OR
          "error": "<error message>"
        },
        ...
      }

    Notes:
    - The function will add "http://" to bare domains or www-prefixed strings
      so urlparse can extract the hostname.
    - Uses ip-api's free JSON endpoint (no API key). Rate limits may apply.
    """
    import re
    from urllib.parse import urlparse
    import requests

    # Helper to trim trailing punctuation commonly attached to URLs in text.
    def _clean_url(s: str) -> str:
        return s.rstrip('.,;:()[]{}<>\"\'')

    urls = []        # preserve insertion order
    seen = set()

    # 1) find explicit http(s) URLs
    for m in re.finditer(r'\bhttps?://[^\s,<>")]+', text, flags=re.IGNORECASE):
        u = _clean_url(m.group(0))
        if u not in seen:
            seen.add(u)
            urls.append(u)

    # 2) find www-prefixed URLs
    for m in re.finditer(r'\bwww\.[^\s,<>")]+', text, flags=re.IGNORECASE):
        u = _clean_url(m.group(0))
        # normalize to include a scheme so urlparse can extract hostname
        normalized = u if u.lower().startswith(('http://','https://')) else 'http://' + u
        if normalized not in seen:
            seen.add(normalized)
            urls.append(normalized)

    # 3) find bare domains (e.g. example.com) but avoid emails and ones already included
    # domain pattern: start with alnum, allow hyphens/dots, TLD 2+ letters
    for m in re.finditer(r'\b([a-zA-Z0-9][a-zA-Z0-9\-\.]+\.[a-zA-Z]{2,})\b', text):
        start = m.start(1)
        # skip if part of an email (preceded by @)
        if start > 0 and text[start - 1] == '@':
            continue
        dom = m.group(1)
        # skip if already present inside any found URL
        already = False
        for u in urls:
            if dom in u:
                already = True
                break
        if not already:
            normalized = 'http://' + dom
            if normalized not in seen:
                seen.add(normalized)
                urls.append(normalized)

    results = {}
    for u in urls:
        # extract hostname
        try:
            parsed = urlparse(u)
            host = parsed.hostname
        except Exception as e:
            results[u] = {"domain": None, "error": f"urlparse_error: {e}"}
            continue

        if not host:
            results[u] = {"domain": None, "error": "no_hostname_extracted"}
            continue

        # Query ip-api for the hostname
        api_url = f'http://ip-api.com/json/{host}?fields=status,message,country,regionName,city,lat,lon,query,isp,org,as,timezone'
        try:
            resp = requests.get(api_url, timeout=timeout)
            # If non-200, still try to parse JSON for an informative message
            data = resp.json()
        except requests.RequestException as e:
            results[u] = {"domain": host, "error": f"request_exception: {e}"}
            continue
        except ValueError:
            results[u] = {"domain": host, "error": "invalid_json_response_from_ip_api"}
            continue

        # ip-api returns {"status":"success", ...} or {"status":"fail","message":"..."}
        if isinstance(data, dict) and data.get("status") == "success":
            results[u] = {"domain": host, "geo": data}
        else:
            # include provided message if available
            msg = data.get("message") if isinstance(data, dict) else "unknown_error"
            results[u] = {"domain": host, "error": msg}

    return results

