import re
import requests

def send_url_to_api(myString, api_url, auth_token):
    # Extract the first URL from the input string
    url_pattern = r'(https?://[^\s]+)'
    match = re.search(url_pattern, myString)

    if match:
        extracted_url = match.group(0)

        # Prepare the payload and headers
        payload = {'url': extracted_url}
        headers = {'Authorization': f'Bearer {auth_token}',
                   'Content-Type': 'application/json'}

        try:
            # Send a POST request to the API
            response = requests.post(api_url, json=payload, headers=headers)

            # Check if the request was successful
            if response.status_code == 200:
                return response.json()  # Return the JSON response
            else:
                return {'error': f'Failed to post. Status code: {response.status_code}', 
                        'response': response.text}

        except requests.exceptions.RequestException as e:
            return {'error': str(e)}

    else:
        return {'error': 'No URL found in the provided string'}

