        while True:
            params = {"per_page": 100, "page": page, "type": "all"}
            resp = requests.get(base_url, params=params, headers=headers, timeout=10)
            if resp.status_code == 404:
                raise ValueError(f"User '{username}' not found (404).")
            if resp.status_code != 200:
                raise RuntimeError(f"GitHub API returned {resp.status_code}: {resp.text}")

            data = resp.json()
            if not isinstance(data, list):
                raise RuntimeError(f"Unexpected response format: {data!r}")

            if not data:
                break

            for item in data:
                name = item.get("name")
                created_at = item.get("created_at")
                if not name or not created_at:
                    continue
                # GitHub uses ISO 8601 with trailing 'Z', e.g. "2020-01-02T03:04:05Z"
                try:
                    dt = datetime.strptime(created_at, "%Y-%m-%dT%H:%M:%SZ")
                except ValueError:
                    # fallback to fromisoformat (handles timezone offset if present)
                    dt = datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                repos.append((dt, name))

            page += 1

    except requests.RequestException as exc:
        raise RuntimeError(f"Network request failed: {exc}")

    # sort by datetime (ascending) and return names
    repos.sort(key=lambda pair: pair[0])
    return [name for (_, name) in repos]
